OPJ_BOOL read_and_decode_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;
    OPJ_UINT8 *current_row = pData;
    OPJ_UINT8 byte;

    while (row < height && fread(&byte, sizeof(OPJ_UINT8), 1, IN) == 1) {
        if (byte == 0x00) {
            // Handle special commands
            fread(&byte, sizeof(OPJ_UINT8), 1, IN);
            switch (byte) {
                case 0x00:
                    // End of line
                    current_row += stride;
                    row++;
                    col = 0;
                    break;
                case 0xFF:
                    // End of bitmap
                    return (pixel_count == expected_pixel_count) ? OPJ_TRUE : OPJ_FALSE;
                case 0x01:
                    // Move cursor
                    fread(&byte, sizeof(OPJ_UINT8), 1, IN);
                    col += byte;
                    break;
                default:
                    // Reserved or unknown command
                    break;
            }
        } else {
            // Handle encoded pixel data
            OPJ_UINT8 first_pixel = byte & 0x0F;
            OPJ_UINT8 second_pixel = (byte >> 4) & 0x0F;

            if (col < width) {
                current_row[col++] = first_pixel;
                pixel_count++;
            }
            if (col < width) {
                current_row[col++] = second_pixel;
                pixel_count++;
            }
        }
    }

    return (pixel_count == expected_pixel_count) ? OPJ_TRUE : OPJ_FALSE;
}

OPJ_BOOL read_and_decode_rle4(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row, col;
    OPJ_UINT32 expected_pixels = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT8 byte;
    OPJ_UINT8* row_ptr = pData;
    OPJ_UINT32 remaining_in_line = width;

    for (row = 0; row < height; row++) {
        OPJ_UINT8* pixel_ptr = row_ptr;
        OPJ_BOOL end_of_line = OPJ_FALSE;

        while (remaining_in_line > 0 && !feof(IN)) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0x01) {
                // End of line
                remaining_in_line = width;
                end_of_line = OPJ_TRUE;
                break;
            }
            else if (byte == 0x02) {
                // End of packet
                return OPJ_TRUE;
            }
            else if (byte == 0x03) {
                // Start of data
                OPJ_UINT8 run_length;
                if (fread(&run_length, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                for (OPJ_UINT32 i = 0; i < run_length; i++) {
                    if (pixel_count < expected_pixels) {
                        *pixel_ptr++ = (byte >> 4) & 0x0F;
                        pixel_count++;
                    }
                    if (pixel_count < expected_pixels) {
                        *pixel_ptr++ = byte & 0x0F;
                        pixel_count++;
                    }
                    remaining_in_line -= 2;
                }
            }
            else {
                // Encoded pixels
                for (OPJ_UINT32 i = 0; i < byte; i++) {
                    if (pixel_count < expected_pixels) {
                        *pixel_ptr++ = (byte >> 4) & 0x0F;
                        pixel_count++;
                    }
                    if (pixel_count < expected_pixels) {
                        *pixel_ptr++ = byte & 0x0F;
                        pixel_count++;
                    }
                    remaining_in_line -= 2;
                }
            }
        }

        if (end_of_line) {
            remaining_in_line = width;
            row_ptr += stride;
        }
    }

    if (pixel_count != expected_pixels) {
        // Output a warning message
        fprintf(stderr, "Warning: Expected %u pixels, but %u were written.\n", expected_pixels, pixel_count);
    }

    return (pixel_count == expected_pixels) ? OPJ_TRUE : OPJ_FALSE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 actual_pixel_count = 0;
    OPJ_UINT32 y;
    OPJ_UINT8* row_ptr;
    OPJ_UINT8 byte;

    if (!IN || !pData || !width || !height) {
        return OPJ_FALSE;
    }

    for (y = 0; y < height; y++) {
        row_ptr = pData + y * stride;

        while (actual_pixel_count < (y + 1) * width) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (feof(IN)) {
                return OPJ_FALSE;
            }

            if ((byte & 0x80) == 0x80) {
                if (byte == 0x80) {
                    /* End of line */
                    break;
                } else if (byte == 0x81) {
                    /* End of bitmap */
                    return (actual_pixel_count == expected_pixel_count) ? OPJ_TRUE : OPJ_FALSE;
                } else if (byte == 0x82) {
                    /* Move forward */
                    OPJ_UINT8 move_count = byte & 0x7F;
                    actual_pixel_count += move_count;
                    row_ptr += move_count;
                } else if (byte == 0x83) {
                    /* Move backward */
                    OPJ_UINT8 move_count = byte & 0x7F;
                    actual_pixel_count -= move_count;
                    row_ptr -= move_count;
                } else {
                    /* Absolute mode */
                    OPJ_UINT8 absolute_count = byte & 0x7F;
                    OPJ_UINT8 pixel;
                    OPJ_UINT32 i;

                    for (i = 0; i < absolute_count; i++) {
                        if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                            return OPJ_FALSE;
                        }

                        *row_ptr++ = pixel;
                        actual_pixel_count++;
                    }
                }
            } else {
                /* Encoded mode */
                OPJ_UINT8 count = byte >> 4;
                OPJ_UINT8 value = byte & 0x0F;
                OPJ_UINT32 i;

                for (i = 0; i < count; i++) {
                    *row_ptr++ = value;
                    actual_pixel_count++;
                }
            }

            if (row_ptr > pData + y * stride + width) {
                return OPJ_FALSE;
            }
        }
    }

    if (actual_pixel_count != expected_pixel_count) {
        /* Warning - pixel count mismatch */
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;
    OPJ_UINT8* row_start = pData;
    OPJ_UINT8 byte;

    while (row < height) {
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if (byte == 0x01) {
            // End of line
            row++;
            col = 0;
            pData = row_start + row * stride;
            continue;
        }

        if (byte == 0x02) {
            // End of bitmap
            if (pixel_count != expected_pixel_count) {
                // Issue warning - this is a simplified example
            }
            return (pixel_count == expected_pixel_count) ? OPJ_TRUE : OPJ_FALSE;
        }

        if (byte == 0x03) {
            // Move
            OPJ_UINT8 move;
            if (fread(&move, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }
            col += move;
            pData += move;
            continue;
        }

        if (byte == 0x00) {
            // End of block (no-op)
            continue;
        }

        // Encoded mode
        OPJ_UINT8 count;
        if (fread(&count, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        OPJ_UINT32 i;
        for (i = 0; i < count; i++) {
            OPJ_UINT8 pixel;
            if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            pData[0] = (pixel >> 4) & 0x0F;
            pData[1] = pixel & 0x0F;
            pData += 2;
            col += 2;
            pixel_count += 2;
        }
    }

    if (pixel_count != expected_pixel_count) {
        // Issue warning - this is a simplified example
    }

    return (pixel_count == expected_pixel_count) ? OPJ_TRUE : OPJ_FALSE;
}

OPJ_BOOL read_and_decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row;
    OPJ_UINT32 col;
    OPJ_UINT8* pRow;
    OPJ_UINT8 byte;
    OPJ_UINT32 expected_pixels = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_BOOL encoded_mode = OPJ_TRUE;
    OPJ_UINT32 repeat_count = 0;
    OPJ_UINT8 repeat_pixel = 0;

    for (row = 0; row < height; row++) {
        pRow = pData + row * stride;

        for (col = 0; col < width; col++) {
            if (!encoded_mode) {
                if (repeat_count > 0) {
                    pRow[col] = repeat_pixel;
                    pixel_count++;
                    repeat_count--;
                    continue;
                }

                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                if (byte == 0x01) {
                    encoded_mode = OPJ_TRUE;
                    continue;
                }

                if (byte == 0x00) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }

                    if (byte == 0x00) {
                        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                            return OPJ_FALSE;
                        }

                        if (byte == 0x01) {
                            break;
                        }

                        if (byte == 0x00) {
                            continue;
                        }

                        pRow[col] = byte;
                        pixel_count++;
                        continue;
                    }

                    pRow[col] = byte;
                    pixel_count++;
                    continue;
                }

                repeat_pixel = byte;
                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                repeat_count = byte;
                encoded_mode = OPJ_FALSE;
                col--;
                continue;
            }

            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0x00) {
                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                if (byte == 0x00) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }

                    if (byte == 0x01) {
                        break;
                    }

                    if (byte == 0x00) {
                        continue;
                    }

                    pRow[col] = byte;
                    pixel_count++;
                    continue;
                }

                pRow[col] = byte;
                pixel_count++;
                continue;
            }

            repeat_pixel = byte;
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            repeat_count = byte;
            encoded_mode = OPJ_FALSE;
            col--;
        }

        if (col != width) {
            continue;
        }

        for (col = 0; col < width; col++) {
            if (repeat_count > 0) {
                pRow[col] = repeat_pixel;
                pixel_count++;
                repeat_count--;
            }
        }

        encoded_mode = OPJ_TRUE;
    }

    if (pixel_count != expected_pixels) {
        fprintf(stderr, "Warning: Actual number of written pixels (%u) does not match expected size (%u).\n", pixel_count, expected_pixels);
    }

    return (pixel_count == expected_pixels) ? OPJ_TRUE : OPJ_FALSE;
}
